fullText:
h1, footer {
  background-color: blue;
}

h1, footer {
  text-align: center;
  color: white;
  margin: 0;
  padding: 12px 0;
}


a {
  text-decoration: none;
  text-shadow: 5px 5px 3px red;
}

a:active {
  font-style: italic;
}


.button-center {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 12px;
}


fieldset {
  border: 2px dotted;
  padding: 10px;
}

label {
  display: inline-block;
  width: 160px;
  margin-bottom: 8px;
}


section {
  padding: 12px;
}


.success { color: green; font-weight: bold; }
.error { color: red; font-weight: bold; }


table {
  border-collapse: collapse;
}
table, th, td {
  border: 1px solid #333;
  padding: 6px 8px;
}

